!function(e){const t="careerQuestProfile",r={name:"",mcpCode:"",currentArea:"",createdAt:null,completed:!1};e.CareerProfileData={PROFILE_STORAGE_KEY:t,DEFAULT_PROFILE:r,getProfile:function(){try{const e=localStorage.getItem(t);return e?{...r,...JSON.parse(e)}:{...r}}catch(e){return console.warn("No se pudo cargar el perfil de Career Quest:",e),{...r}}},saveProfile:function(e){const o={...r,...e,createdAt:e.createdAt||(new Date).toISOString(),completed:!0};return localStorage.setItem(t,JSON.stringify(o)),o},clearProfile:function(){localStorage.removeItem(t)}}}(window);